//! Hashes of the generated files, for testing checksum checks.

use base64::Engine;
use md5::Md5;
use sha2::{Digest, Sha256, Sha512};

use crate::fill_content;

/// Hashes of the first `size` generated bytes, as raw bytes.
pub struct Hashes {
    pub md5: Vec<u8>,
    pub sha256: Vec<u8>,
    pub sha512: Vec<u8>,
}

pub fn hashes_of(size: u64) -> Hashes {
    let (mut md5, mut sha256, mut sha512) = (Md5::new(), Sha256::new(), Sha512::new());
    let mut buffer = vec![0u8; 64 * 1024];
    let mut offset = 0u64;
    while offset < size {
        let n = usize::try_from((size - offset).min(buffer.len() as u64)).unwrap();
        fill_content(offset, &mut buffer[..n]);
        md5.update(&buffer[..n]);
        sha256.update(&buffer[..n]);
        sha512.update(&buffer[..n]);
        offset += n as u64;
    }
    Hashes {
        md5: md5.finalize().to_vec(),
        sha256: sha256.finalize().to_vec(),
        sha512: sha512.finalize().to_vec(),
    }
}

pub fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

pub fn base64(bytes: &[u8]) -> String {
    base64::engine::general_purpose::STANDARD.encode(bytes)
}

/// The text of a checksum file for `size` bytes under `algorithm`.
/// `style`: `plain` (hash and name), `lone` (only the hash), `list` (several
/// files, ours among them), `other` (a list that does not mention our file),
/// `wrong` (a hash that does not match).
pub fn checksum_file(size: u64, algorithm: &str, style: &str) -> Option<String> {
    let h = hashes_of(size);
    let real = match algorithm {
        "md5" => hex(&h.md5),
        "sha256" => hex(&h.sha256),
        "sha512" => hex(&h.sha512),
        _ => return None,
    };
    let name = "mohona-test.bin";
    let wrong = "0".repeat(real.len());
    Some(match style {
        "lone" => format!("{real}\n"),
        "list" => format!("{wrong}  other-file.bin\n{real}  {name}\n"),
        "other" => format!("{wrong}  other-file.bin\n"),
        "wrong" => format!("{wrong}  {name}\n"),
        _ => format!("{real}  {name}\n"),
    })
}
